'''Current public copy and generated estimate reference.'''
import json
from html import escape
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
CATALOG=json.loads((ROOT/'content/catalog.json').read_text())
FAQ=json.loads((ROOT/'content/faq.json').read_text())

def section(title,text):
    return f'<section class="section wrap prose"><h2>{title}</h2>{text}</section>'

def custom_pages(intro,cta):
    cards=[]
    for p in json.loads((ROOT/'content/packages.json').read_text()):
        extra='<li>Quarterly Search &amp; AI Visibility summary</li>' if p['name']=='Growth' else ''
        cards.append(f'''<article class="price-card"><p class="eyebrow">{p['name']}</p><h2>${p['development']:,}<span> to build</span></h2><p class="monthly">+ ${p['monthly']}<span> / month</span></p><p>{'A professional website to explain your services and generate inquiries.' if p['name']=='Essential' else 'More room for your services and a regular look at search visibility.'}</p><ul><li>Up to {p['pages']} pages tailored to your business</li><li>Mobile-friendly design and standard contact form</li><li>Basic search setup</li><li>Hosting and basic website monitoring</li><li>{p['edits']} minor update{'s' if p['edits']>1 else ''} per month</li>{extra}<li>Ownership after development is paid in full</li></ul><a class="button" href="/contact/?plan={p['name'].lower()}">Talk about {p['name']} ↗</a></article>''')
    enterprise=next(i for i in CATALOG['items'] if i['id']=='enterprise')
    cards.append(f'''<article class="price-card enterprise-card"><p class="eyebrow">Enterprise</p><h2>${enterprise['monthly']}<span> / month</span></h2><p class="monthly">12-month commitment</p><p>A custom website with development, hosting, and agreed support in one monthly plan.</p><ul><li>No separate development fee for the agreed build</li><li>Billing begins at kickoff</li><li>$4,800 total over the first 12 months</li><li>Page count, features, and support agreed before work starts</li><li>Own your website after all 12 payments</li><li>Ongoing hosting and support after year one quoted separately</li></ul><a class="button" href="/contact/?plan=enterprise">Talk about Enterprise ↗</a></article>''')
    websites=intro('Custom websites & pricing','Custom websites.<br>Clear pricing.','A website should explain your business, help your customers, and make the next step easy. Before work begins, you’ll receive a clear scope, an upfront price, and an ongoing monthly total.')
    websites+='<section class="wrap pricing-section"><div class="prices">'+''.join(cards)+'</div><div class="policy-strip"><p><strong>Essential &amp; Growth: 50% to start · 50% on completion</strong><br>Essential and Growth hosting is month-to-month after development is paid.</p><p><strong>A complete starting point</strong><br>Business email, domains, booking and staff editing are separately scoped when needed.</p></div></section>'
    websites+=section('Need your website to do more?','<p>Staff editing, appointment scheduling, business email, reviews displays, payments, additional domains, and connected workflows can be included in a configuration built around your needs.</p><p>These capabilities can change the build and monthly price. We recommend a complete configuration and show you the total before you commit. Specialized features require a requirements and feasibility review.</p><p>Standard tools for your agreed configuration are included in its monthly price. Advertising spend, payment processing, taxes, and exceptional purchases are identified separately when applicable.</p><div class="actions"><a class="button" href="/ask-jasper/">Explore with Jasper ↗</a><a class="text-link" href="/contact/">Get a complete quote ↗</a></div>')
    websites+=section('What your monthly payment covers','<p>Essential and Growth include hosting, basic monitoring, and the listed update allowance. Additional configurations include the agreed software, infrastructure, and support for those systems. Your proposal identifies features and usage limits.</p>')
    websites+=section('A few things to know','<p><strong>Content:</strong> you supply final written content, images, branding, and business information. Content production is outside these packages.</p><p><strong>Minor updates:</strong> small changes to existing hours, contact details, or a short text correction. New pages and features are separately scoped.</p><p><strong>Additional work:</strong> $75/hour, $37.50 minimum, agreed before starting. Existing client agreements remain in effect.</p><p><strong>Ownership:</strong> your website is yours after development is paid. Third-party software retains its provider’s terms. We help coordinate a reasonable transfer if you leave.</p><p><a href="/faq/">Read all frequently asked questions ↗</a></p>')
    websites+=section('Larger projects and online stores','<p>Enterprise is $400/month for 12 months, with ownership after all 12 payments. The agreed proposal defines the build, support, any additional capabilities, and early departure obligations. Hosting and support after the initial year are agreed separately. E-commerce and specialized projects receive an individual proposal.</p><p>For online stores, standard platform costs are included in the agreed monthly configuration. Payment processing and transaction fees remain separate.</p>')+cta()
    about=intro('About Think Marketing','Your domain is the land.<br>Let’s build what your business needs.','A domain name is a little like a plot of land. It gives you a place to build, but what you do with it depends on your vision.')
    about+=section('From a starting point to something useful','<p>You could build a house, a hotel, or a working farm. Each serves a different purpose and needs a different plan.</p><p>Your website is much the same. It might introduce your business, answer customer questions, book appointments, collect inquiries, or support daily operations.</p><p><strong>Think Marketing is the bridge between that starting point and what you want to create.</strong></p>')
    about+=section('Custom websites for small and medium-sized businesses','<p>Based in Bend, Oregon, Think Marketing helps businesses turn their ideas into useful websites.</p><p>We start by understanding what you do, who your customers are, and what you want your website to accomplish. That understanding shapes the design, information, and functionality we recommend.</p><p>Two questions guide the work.</p>')
    about+='<section class="section wrap philosophy-grid"><article><p class="eyebrow">Question one</p><h2>Is your website an expert on what you do?</h2><p>Your website should explain your services clearly and answer the questions customers ask before contacting you. Your experience and expertise should come through.</p><p>We organize the information you provide into a website customers can understand.</p></article><article><p class="eyebrow">Question two</p><h2>Is your website your most valuable employee?</h2><p>That’s the goal we work toward. A useful website can answer questions after hours, guide an inquiry, help someone book an appointment, or make a routine task easier.</p><p>We help you identify where your website can contribute and what makes sense to build.</p></article></section>'
    about+=section('A clear plan and a practical investment','<p>You should understand what you’re buying. We explain the scope, upfront cost, monthly service, and responsibilities before work begins.</p><p>Your website can grow with your business. Our job is to help you build with purpose at each stage.</p><div class="actions"><a class="button" href="/websites/">Explore website pricing ↗</a><a class="text-link" href="/ask-jasper/">Ask Jasper ↗</a></div>')+cta()
    faq=intro('Frequently asked questions','Questions before we build.','Straight answers about website pricing, ownership, support, and what to expect.')
    faq+='<section class="section wrap faq" aria-label="Frequently asked questions">'+''.join(f'<details id="question-{n+1}"><summary>{escape(f["question"])}</summary><p>{f["answer"]}</p></details>' for n,f in enumerate(FAQ))+'</section>'
    faq+=section('Want to explore your options?','<p><a href="/ask-jasper/">Ask Jasper</a> for guided answers and a starting estimate, or contact Think Marketing to talk through your project.</p>')+cta()
    jasper=intro('Ask Jasper · guided preview','A clearer starting point<br>for your website.','Explore packages, ask common questions, and build an estimate. Jasper’s first version uses guided answers and a pricing calculator; open-ended AI chat is still in development.')
    jasper+='<section class="section wrap jasper-layout"><div class="jasper-panel"><p class="eyebrow">Explore a question</p><h2>What would you like to know?</h2><form id="jasper-question"><label for="question">Your website question</label><div class="question-input"><input id="question" name="question" type="text" maxlength="500" placeholder="For example: can I update my site?" required><button class="button" type="submit">Find an answer</button></div></form><div class="topic-buttons"><button type="button" data-topic="pricing">Pricing</button><button type="button" data-topic="editing">Staff editing</button><button type="button" data-topic="booking">Booking &amp; calendars</button><button type="button" data-topic="ownership">Ownership</button><button type="button" data-topic="ai">AI visibility</button></div><div id="jasper-answer" class="jasper-answer" role="status"><p>Start with a question or choose a topic. For project-specific advice, <a href="/contact/">talk with Think Marketing</a>.</p></div><p class="fine">Your questions stay in this browser and are not saved or sent to an AI provider. This preview matches common topics; it may not understand every question.</p></div><aside class="jasper-panel"><p class="eyebrow">A useful website starts here</p><h2>What should it do for you?</h2><ul><li>Explain your services and answer questions</li><li>Let staff update agreed information</li><li>Help customers book appointments</li><li>Connect inquiries to your existing workflow</li></ul><p>Choose the closest starting point below. A human confirms scope, feasibility, and the final proposal.</p><a class="text-link" href="/faq/">Browse all FAQs ↗</a></aside></section>'
    jasper+='<section class="section wrap" id="estimate"><div class="section-head"><p class="eyebrow">Build a starting estimate</p><h2>One setup total. One monthly total.</h2><p>Standard tools are included within each service’s limits. Choose only the capabilities you need.</p></div><form id="estimate-form"><div class="estimate-controls"><label for="website-plan">Your website starting point<select id="website-plan"><option value="essential">New Essential website — $1,995 + $50/month</option><option value="growth">New Growth website — $2,500 + $80/month</option><option value="enterprise">Enterprise — $400/month for 12 months; own after year one</option><option value="existing">I have a website / quote add-ons only</option></select></label></div><div class="estimate-grid">'
    for id in ('email','scheduling','admin','domain','reviews','form'):
        item=next(i for i in CATALOG['items'] if i['id']==id)
        extras=f' First {item["unit"]} setup ${item["setup"]}; additional {item["unit"]} setup ${item["additional_setup"]}.' if item['additional_setup'] is not None else ''
        jasper+=f'<label class="estimate-item" for="qty-{id}"><span class="estimate-name">{escape(item["name"])}</span><span>${item["monthly"]}/month per {escape(item["unit"])} · setup ${item["setup"]}</span><span class="fine">{escape(extras or item["scope"])}</span><span class="quantity-label">Quantity ({escape(item["unit"])})</span><input id="qty-{id}" data-service="{id}" type="number" value="0" min="0" max="100" step="1"></label>'
    jasper+='</div><div class="actions"><button type="button" id="example-estimate" class="button">Try the 3-person business example</button><button type="reset" class="text-button">Reset</button></div></form><p class="fine">Staff email includes its normal calendar. Add scheduling only for public appointment bookings. Domains here are additional managed standard domains; registration and renewal are included. Premium names require a confirmed quote.</p><div id="estimate-result" class="estimate-result" role="status" aria-live="polite">Loading the estimator…</div><noscript><p>The calculator needs JavaScript. Essential is $1,995 + $50/month; Growth is $2,500 + $80/month. Enterprise is $400/month for 12 months ($4,800 total), with ownership after all 12 payments. <a href="/contact/">Contact us for an estimate</a>.</p></noscript><div class="actions"><a class="button" id="email-estimate" href="mailto:thinkmarketingbend@gmail.com?subject=Website%20estimate">Discuss this estimate ↗</a><a class="text-link" href="/estimate-reference/">Full service estimate reference ↗</a></div><p class="fine">Estimates are informational, valid 30 days, and subject to requirements and availability. No discounts are assumed. This page doesn’t place an order or send a message. The contact link opens your email app for you to review and send.</p></section><script type="module" src="/assets/js/jasper.mjs"></script>'
    marketing=intro('Marketing','One business.<br>A connected marketing plan.','Choose the right next step: decide where to focus, help customers find you, or reach people through paid search. Local SEO and AI/search visibility support the same business presence.')
    marketing+='<section class="section wrap marketing-overview"><article><p class="eyebrow">01 · Plan</p><h2>Marketing consulting</h2><p>Decide what to improve, where to invest, and what can wait. Start here if you need a direction before choosing a service.</p><a class="text-link" href="#consulting">Explore consulting ↗</a></article><article><p class="eyebrow">02 · Get found</p><h2>Search &amp; local visibility</h2><p>Help people find and understand your business in Google Maps, search results, and AI answers. Local SEO and AI visibility are connected parts of this work.</p><a class="text-link" href="#visibility">Find your visibility starting point ↗</a></article><article><p class="eyebrow">03 · Reach customers</p><h2>Paid search</h2><p>Reach people searching for your services with focused Google Search campaigns, agreed management, and a separate advertising budget.</p><a class="text-link" href="#paid-search">Explore paid search ↗</a></article></section>'
    marketing+='<div id="consulting">'+section('Marketing consulting','<p>Assess what you have, decide what matters next, and prioritize a realistic budget. A 60-minute consultation is $125. A marketing action plan starts at $350 and includes a meeting and concise written priorities.</p><p>Ongoing consulting is available at $250/month, plus $150 onboarding: one 60-minute meeting, preparation, and up to 30 minutes of follow-up. Implementation is separate.</p>')+'</div>'
    marketing+='<section class="section wrap" id="visibility"><div class="section-head"><p class="eyebrow">One connected presence</p><h2>Search &amp; local visibility</h2><p>Customers may discover you through Maps, a search result, or an AI answer. Clear business information and a useful website support all three.</p></div><div class="visibility-pair"><article><h3>Local SEO</h3><p>Your nearby presence: Google Business Profile, accurate business listings, service areas, and a website that explains what you do and where you work.</p><p>Profile creation assistance: $200. Cleanup and ongoing improvements are separately scoped.</p><a class="text-link" href="/local-seo/">Explore local SEO ↗</a></article><article><h3>AI &amp; search visibility</h3><p>Your discoverable expertise: page access, clear service information, useful answers, and dated observations of how search and AI services represent your business.</p><p>Combined Search &amp; AI Visibility Review: $350. Implementation is separate.</p><a class="text-link" href="/ai-search-visibility/">Explore the visibility review ↗</a></article></div><div class="policy-strip"><p><strong>You may need one, both, or an assessment first.</strong><br>We scope the work around the gap. Shared checks, profile maintenance, and reporting should not be billed twice.</p><p><strong>One recommended plan.</strong><br>Choose an agreed scope and total; you do not need to buy every service. Rankings, recommendations, and lead volumes are not guaranteed.</p></div></section>'
    marketing+='<div id="paid-search">'+section('Google Search PPC','<p><strong>$500 setup + $350/month management.</strong> For one business, up to two Google Search campaigns and up to $2,500/month advertising spend.</p><p>Campaign configuration, campaign ad text, conversion setup, routine optimization, and monthly reporting are included. Advertising spend is additional and paid to Google. Landing pages are separately scoped. Larger accounts require a custom quote.</p><p>Campaign scope and availability are confirmed before work begins. Results and lead volumes are not guaranteed.</p>')+'</div>'
    marketing+=section('Where does your website fit?','<p>Your website is the foundation: a place to explain your expertise and help customers take action. Marketing helps the right people reach it and understand why your business fits their needs.</p><p><a href="/websites/">Explore custom websites</a>, <a href="/ask-jasper/">ask Jasper</a>, or talk with us about a sensible next step.</p>')+cta()
    reference=intro('Estimate reference','Service scope &amp; estimate pricing.','The detailed reference behind Jasper’s estimates. Standard tools are included within the limits below. Final scope and availability require Think Marketing confirmation.')
    reference+='<section class="section wrap"><p><a href="/ask-jasper/">Return to Ask Jasper ↗</a> · <a href="/estimate-reference/catalog.json">Read the pricing catalog</a></p><p class="fine">Catalog '+escape(CATALOG['version'])+'. Additional work: $75/hour, $37.50 minimum. Feature fees are additional to base website hosting. Advertising spend, payment processing, taxes, and approved exceptional purchases remain separate.</p><div class="reference-list">'
    for item in CATALOG['items']:
        prefix='From ' if item['price_kind']=='from' else ''
        extra=f' Additional {item["unit"]} setup: ${item["additional_setup"]}.' if item['additional_setup'] is not None else ''
        reference+=f'<article><h2>{escape(item["name"])}</h2><p><strong>{prefix}${item["setup"]:,} setup / one-time + {prefix if item["monthly"] else ""}${item["monthly"]:,}/month</strong> · per {escape(item["unit"])}</p><p>{escape(item["scope"])}{escape(extra)}</p></article>'
    reference+='</div></section>'
    return {'websites':('Website pricing',websites),'about':('About Think Marketing',about),'faq':('Frequently asked questions',faq),'ask-jasper':('Ask Jasper',jasper),'marketing':('Marketing services',marketing),'estimate-reference':('Estimate reference',reference)}
